-- public.skills
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('35e92aae-a4fd-5bb1-a86b-4114f7a38fda'::uuid, 'RMR-SK-L01-M01', 'Observe the Prepared Water Settle', 'Compare the initial cloudy jar and the settled layers without shaking the jar. Record the liquid and sediment observations at the named times. Produce: A settling observation log with an accurate explanation of what stayed in the jar. Avoid: Settling does not prove that water is safe to drink.', '["Class 6", "Level 1", "The Muddy Water Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 1, "module": 1, "case_source": "Model A muddy-water jar; starting water 200 mL, soil 5 g, settling time 15 min.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('6a33267c-7a40-5892-9f1e-9cc3e53be70b'::uuid, 'RMR-SK-L01-M02', 'Transfer and Filter', 'Decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings. Produce: Transfer-and-filtration evidence with the collected volume. Avoid: Clearer appearance is not proof of drinking-water safety.', '["Class 6", "Level 1", "The Muddy Water Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 1, "module": 2, "case_source": "Jar A after settling; Jar B collected 185 mL; Cup C after filtration 175 mL (worked model).", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('846598fd-c6cd-5abf-90fe-76c2274bc65f'::uuid, 'RMR-SK-L01-M03', 'Calculate the Collected Volume', 'Match vessel and volume; subtract 200 - 175 = 25 mL; simplify 25/200 = 1/8; calculate 12.5% not collected and 87.5% collected. Produce: A labelled volume, fraction and percentage calculation record. Avoid: The 25 mL difference is not the dry mass of mud removed.', '["Class 6", "Level 1", "The Muddy Water Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 1, "module": 3, "case_source": "Worked model: Jar A start 200 mL, Jar B 185 mL, Cup C final 175 mL.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('f9817933-3316-5c68-b969-ac3d72ef2451'::uuid, 'RMR-SK-L01-M04', 'Prepare the School-Tank Evidence Note', 'Use the supported volume and observation records; distinguish what separation shows from what drinking-water safety would require; prepare a short note. Produce: A school-tank evidence note with findings, limits and a next step. Avoid: Do not claim that the school tank is safe to drink from.', '["Class 6", "Level 1", "The Muddy Water Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 1, "module": 4, "case_source": "Worked jar and filter results, with a separate school-tank decision question.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('192e8809-8b84-58b1-8ea1-c1fb63a3f769'::uuid, 'RMR-SK-L02-M01', 'Test the Three Coded Liquids', 'Keep cup IDs separate; compare each recorded strip before and after testing; enter the colour observation without assuming the category. Produce: A coded-sample litmus observation table. Avoid: A colour observation should not be replaced by an invented result.', '["Class 7", "Level 2", "The Invisible Difference Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 2, "module": 1, "case_source": "Three coded cups and separate red/blue litmus observations shown in the lesson.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('7dbf6d49-e5a1-5d83-a365-b8476aa6cbaa'::uuid, 'RMR-SK-L02-M02', 'Investigate the Cup B Conflict', 'Retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions. Produce: A Cup B discrepancy and controlled-retest log. Avoid: Do not claim contamination or another cause unless proven.', '["Class 7", "Level 2", "The Invisible Difference Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 2, "module": 2, "case_source": "B-T1 blue turns red; B-T2 unchanged with missing conditions; worked B-T3 fresh blue turns red.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('38f0549b-e37e-5b72-b6cc-5eef5d7f3d9c'::uuid, 'RMR-SK-L02-M03', 'Observe the Turmeric Response', 'Record original indicator colour and visible colour after contact; compare with the provided reference and the litmus log. Produce: A turmeric observation and cross-indicator comparison. Avoid: Colour must be observed or supplied; do not fabricate a reaction.', '["Class 7", "Level 2", "The Invisible Difference Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 2, "module": 3, "case_source": "The turmeric and liquid-sample observations displayed in the module.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('f659f619-0b28-59e3-9591-d807c864010d'::uuid, 'RMR-SK-L02-M04', 'Finish the Cost and Finding Log', 'Multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports. Produce: A verified cost calculation and scientific finding log. Avoid: A low testing cost does not make incomplete findings conclusive.', '["Class 7", "Level 2", "The Invisible Difference Challenge", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 2, "module": 4, "case_source": "Strip counts, stated unit prices, the available budget and observation records in the module.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('9b7c3a9c-001a-5615-b978-7876c08ee0a6'::uuid, 'RMR-SK-L03-M01', 'Compare the Two Field Reports', 'Align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly. Produce: A two-report comparison and list of missing controls. Avoid: Different conditions must not be presented as a controlled experiment.', '["Class 8", "Level 3", "The River After Rain", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 3, "module": 1, "case_source": "Field reports F1 and F2 with site, rainfall and land-cover details.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('a01fa0a5-71dc-59d3-9d8a-3a09d77381e3'::uuid, 'RMR-SK-L03-M02', 'Build a Matched Runoff Comparison', 'Compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings. Produce: A matched runoff setup and measurement record. Avoid: Do not assign sediment scores without recorded observations.', '["Class 8", "Level 3", "The River After Rain", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 3, "module": 2, "case_source": "Bare-soil and leaf-covered trays; collection vessels and matched input conditions.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('77e230b8-dc85-5e48-8bf1-58a98de147f4'::uuid, 'RMR-SK-L03-M03', 'Calculate Runoff Across Three Trials', 'Calculate means 160 mL and 100 mL; compute 64% and 40% runoff; report the 24-percentage-point gap. Produce: A three-trial mean, percentage and comparison table. Avoid: 24 percentage points is a runoff-share gap, not dry soil mass lost.', '["Class 8", "Level 3", "The River After Rain", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 3, "module": 3, "case_source": "Bare runoff: 150, 160, 170 mL; covered: 90, 100, 110 mL; input 250 mL per trial.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('bbdbf1cb-f668-58df-af73-2902f9255e4b'::uuid, 'RMR-SK-L03-M04', 'Write a Fair Field-Study Proposal', 'Specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited. Produce: A fair field-study proposal with evidence and next actions. Avoid: Missing slope or rainfall controls must be made explicit.', '["Class 8", "Level 3", "The River After Rain", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 3, "module": 4, "case_source": "Existing runoff report findings and identified missing conditions.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('1818015d-8c08-5e8b-8d3e-5a84972a1ff0'::uuid, 'RMR-SK-L04-M01', 'Calculate Salt Solution Concentration', 'Identify mass and volume from the same mixture, apply the taught concentration expression and record the correct units. Produce: A source-linked salt-solution concentration calculation. Avoid: Do not invent a concentration without both source quantities.', '["Class 9", "Level 4", "The Filter Claim Under Test", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 4, "module": 1, "case_source": "The salt mass and solution-volume record supplied in the module.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('2e65a174-4186-5148-bd36-39a45d401ae1'::uuid, 'RMR-SK-L04-M02', 'Inspect What Paper Filtration Retains', 'Distinguish source solutions, observe what the paper retains, and document the filtrate without merging their samples. Produce: A two-sample filtration observation and scientific explanation. Avoid: Visible filtration alone does not prove dissolved salt removal.', '["Class 9", "Level 4", "The Filter Claim Under Test", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 4, "module": 2, "case_source": "Separate SOIL-S and SOL-B filtration records and apparatus shown in the module.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('60ca4b36-c3b6-5a36-8d32-39e9a7d93598'::uuid, 'RMR-SK-L04-M03', 'Review the Mock Dried-Residue Record', 'Subtract each dish tare from its paired final mass: 4.90 g and 4.85 g; compare 0.05 g and flag missing preparation controls. Produce: A paired dish-mass calculation and validity note. Avoid: No supported salt-removal percentage without comparable aliquots and controls.', '["Class 9", "Level 4", "The Filter Claim Under Test", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 4, "module": 3, "case_source": "Mock B-PRE tare 32.10 g/final 37.00 g; B-POST tare 31.60 g/final 36.45 g.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('57f760a2-90cb-549a-afdd-e5f042d35c06'::uuid, 'RMR-SK-L04-M04', 'Evaluate the Filter Advertisement', 'Quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision. Produce: A claim-check decision with evidence and limitations. Avoid: Do not claim that dissolved salt removal was verified.', '["Class 9", "Level 4", "The Filter Claim Under Test", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 4, "module": 4, "case_source": "The filter advertisement, filtration observations and mock residue evidence.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('3102c5c7-3436-5f6b-bb9f-b5f48d73500c'::uuid, 'RMR-SK-L05-M01', 'Compare Teacher-Prepared Reference Liquids', 'Match each strip to its own sample, compare observed colours with the correct kit chart and record the classification. Produce: A sample-by-sample indicator evidence table. Avoid: The reference chart must be supplied; pH or appearance alone is not safety proof.', '["Class 10", "Level 5", "The River That Looks Clean", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 5, "module": 1, "case_source": "Teacher-prepared reference samples, indicator strips and the applicable manufacturer chart.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('4bd6546c-88e9-58f2-8da5-b3155525795e'::uuid, 'RMR-SK-L05-M02', 'Read the Separate Mock Meter QC', 'Match instrument and reference IDs, inspect calibration evidence, record any accepted or missing QC result. Produce: An instrument quality-control review note. Avoid: Do not treat mock QC as a verified reading from a physical meter.', '["Class 10", "Level 5", "The River That Looks Clean", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 5, "module": 2, "case_source": "Separate mock PH-07 meter QC evidence, distinct from the R-26 sample report.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('12029796-9920-55c2-9af9-574b3b42f617'::uuid, 'RMR-SK-L05-M03', 'Review an Unverified Acid-Base Protocol', 'List the described steps, identify the missing starting and final evidence and classify the outcome as unverified. Produce: A procedure audit showing the observations still needed. Avoid: Do not manufacture an acid-base change or claim an experiment was completed.', '["Class 10", "Level 5", "The River That Looks Clean", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 5, "module": 3, "case_source": "Acid-base procedure without verified before-and-after observations.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('c9b11df7-5e3b-58eb-895f-e327cc561782'::uuid, 'RMR-SK-L05-M04', 'Interpret the Fictional R-26 Report', 'Keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators. Produce: An R-26 report interpretation and missing-evidence log. Avoid: These pH values do not certify water as safe to drink.', '["Class 10", "Level 5", "The River That Looks Clean", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 5, "module": 4, "case_source": "Fictional R-26-A pH 7.1; B pH 5.2; C pH 8.8; source and safety metadata missing.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."skills" ("id", "code", "name", "description", "tags", "metadata")
VALUES ('d81623aa-7f25-5a70-90dd-cea14eb104f5'::uuid, 'RMR-SK-L05-M05', 'Prepare the Water-Authority Handover', 'Summarise verified observations, missing measurements, limits and the responsible next testing or referral action. Produce: A water-authority handover note with evidence and unresolved questions. Avoid: No water-use clearance without the necessary accredited safety testing.', '["Class 10", "Level 5", "The River That Looks Clean", "Science", "Evidence", "Applied learning"]'::jsonb, '{"level": 5, "module": 5, "case_source": "Completed Level 5 sample, pH, instrument and source-evidence reviews.", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT DO NOTHING;



