INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('03bd758a-832c-5e49-92ff-9119d32994a5'::uuid, 'RMR-L01', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RMR-CAP-L01'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 1), 'River Mission Level 1 - The Muddy Water Challenge', 'Class 6 applied learning: Investigate muddy water using settling, decantation and filtration. Read starting and final volumes, explain the difference and prepare a school-tank evidence note.', '["Inspect supplied evidence", "Perform the actual module calculation or comparison", "Record source IDs and units", "Explain the scientific limit", "Complete independent evidence and handover"]'::jsonb, '["Settling log", "filtration record", "volume calculation", "school-water evidence note"]'::jsonb, '{"title": "The Muddy Water Challenge", "description": "A school water team receives muddy water and must observe settling, separate the clearer liquid, measure what is collected, and explain what the experiment does not prove."}'::jsonb, 45, 'beginner'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"class": 6, "level": 1, "subjects": ["Science", "Mathematics", "Environmental Studies", "Communication"], "6e_order": ["engage", "explore", "explain", "express", "empower", "evolve"], "module_count": 4, "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "status" = EXCLUDED."status";
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('91ce2164-4d53-5ef3-adb1-691e2c6c4209'::uuid, 'RMR-L02', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RMR-CAP-L02'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 2), 'River Mission Level 2 - The Invisible Difference Challenge', 'Class 7 applied learning: Compare similar-looking liquid samples using indicators. Document conflicting observations, examine a turmeric response and complete a cost-and-finding log.', '["Inspect supplied evidence", "Perform the actual module calculation or comparison", "Record source IDs and units", "Explain the scientific limit", "Complete independent evidence and handover"]'::jsonb, '["Litmus observation log", "conflicting-test review", "turmeric comparison", "cost-and-finding log"]'::jsonb, '{"title": "The Invisible Difference Challenge", "description": "Three similar-looking liquids give different indicator evidence. The student team must record tests, investigate a conflict and report reliable observations without guessing."}'::jsonb, 45, 'foundation'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"class": 7, "level": 2, "subjects": ["Science", "Mathematics", "Environmental Studies", "Communication"], "6e_order": ["engage", "explore", "explain", "express", "empower", "evolve"], "module_count": 4, "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "status" = EXCLUDED."status";
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('33cad490-ae39-590a-8121-182638ceff97'::uuid, 'RMR-L03', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RMR-CAP-L03'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 3), 'River Mission Level 3 - The River After Rain', 'Class 8 applied learning: Compare bare and leaf-covered soil runoff using field records and matched trials. Calculate average runoff, interpret percentage-point differences and propose a fair field study.', '["Inspect supplied evidence", "Perform the actual module calculation or comparison", "Record source IDs and units", "Explain the scientific limit", "Complete independent evidence and handover"]'::jsonb, '["Field report comparison", "matched runoff setup", "trial calculation table", "fair field-study proposal"]'::jsonb, '{"title": "The River After Rain", "description": "Rainwater runs off bare and covered ground differently. The team must compare field reports, set matched conditions, calculate runoff and design a fair field study."}'::jsonb, 45, 'intermediate'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"class": 8, "level": 3, "subjects": ["Science", "Mathematics", "Environmental Studies", "Communication"], "6e_order": ["engage", "explore", "explain", "express", "empower", "evolve"], "module_count": 4, "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "status" = EXCLUDED."status";
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('2d9bfea5-c15f-5b7c-9705-c43a9a950d17'::uuid, 'RMR-L04', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RMR-CAP-L04'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 4), 'River Mission Level 4 - The Filter Claim Under Test', 'Class 9 applied learning: Compare suspended soil and dissolved salt, review filtration and mock residue evidence, calculate concentration or mass differences and evaluate a filter advertisement cautiously.', '["Inspect supplied evidence", "Perform the actual module calculation or comparison", "Record source IDs and units", "Explain the scientific limit", "Complete independent evidence and handover"]'::jsonb, '["Concentration calculation", "two-sample filtration observations", "dried-residue record", "advertisement claim check"]'::jsonb, '{"title": "The Filter Claim Under Test", "description": "A seller claims a filter removes impurities. The team must distinguish soil from dissolved salt, check mock residue calculations and judge what the evidence supports."}'::jsonb, 45, 'advanced'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"class": 9, "level": 4, "subjects": ["Science", "Mathematics", "Environmental Studies", "Communication"], "6e_order": ["engage", "explore", "explain", "express", "empower", "evolve"], "module_count": 4, "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "status" = EXCLUDED."status";
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('d3772820-8f5a-53d8-ad3a-ae2299f8de36'::uuid, 'RMR-L05', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RMR-CAP-L05'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 5), 'River Mission Level 5 - The River That Looks Clean', 'Class 10 applied learning: Review water samples, pH evidence and instrument records. Identify unverified procedures, interpret a fictional R-26 report and prepare a responsible water-authority handover.', '["Inspect supplied evidence", "Perform the actual module calculation or comparison", "Record source IDs and units", "Explain the scientific limit", "Complete independent evidence and handover"]'::jsonb, '["Reference-liquid record", "meter QC review", "protocol evidence audit", "R-26 report", "authority handover"]'::jsonb, '{"title": "The River That Looks Clean", "description": "Water samples look clear, but their safety is unknown. The team must examine pH information, inspect mock instrument records and report missing tests before advising an authority."}'::jsonb, 45, 'advanced'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"class": 10, "level": 5, "subjects": ["Science", "Mathematics", "Environmental Studies", "Communication"], "6e_order": ["engage", "explore", "explain", "express", "empower", "evolve"], "module_count": 5, "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
