VALUES ('6f186474-f8b8-5325-b6f6-de400efdd3dd'::uuid, '03bd758a-832c-5e49-92ff-9119d32994a5'::uuid, 1, 'Observe the Prepared Water Settle', 'Solve the connected River Mission challenge: Cloudy water is mixed with soil; the liquid changes after standing. Deliverable: A settling observation log with an accurate explanation of what stayed in the jar.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'A school water team receives muddy water and must observe settling, separate the clearer liquid, measure what is collected, and explain what the experiment does not prove.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Compare the initial cloudy jar and the settled layers without shaking the jar. Record the liquid and sediment observations at the named times.", "Explain the limits of the result", "Create A settling observation log with an accurate explanation of what stayed in the jar."]'::jsonb, 'Use this module when investigating: Cloudy water is mixed with soil; the liquid changes after standing.', '{"major_concepts": "Observe the Prepared Water Settle", "practical_operation": "Compare the initial cloudy jar and the settled layers without shaking the jar. Record the liquid and sediment observations at the named times.", "source": "Model A muddy-water jar; starting water 200 mL, soil 5 g, settling time 15 min."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Observe the Prepared Water Settle; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'Cloudy water is mixed with soil; the liquid changes after standing.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 6, "level": 1, "capability_id": "RMR-CAP-L01-M01", "source_record": "Model A muddy-water jar; starting water 200 mL, soil 5 g, settling time 15 min.", "limitation": "Settling does not prove that water is safe to drink.", "drive_folder": "https://drive.google.com/drive/folders/1b_FikrgkX2BmC8YPxhN1BZduNLZew37c", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
