VALUES ('0abe0211-71f9-5fac-a64b-c884acc0e576'::uuid, '03bd758a-832c-5e49-92ff-9119d32994a5'::uuid, 2, 'Transfer and Filter', 'Solve the connected River Mission challenge: We must collect clearer liquid without carrying all the sediment. Deliverable: Transfer-and-filtration evidence with the collected volume.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'A school water team receives muddy water and must observe settling, separate the clearer liquid, measure what is collected, and explain what the experiment does not prove.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings.", "Explain the limits of the result", "Create Transfer-and-filtration evidence with the collected volume."]'::jsonb, 'Use this module when investigating: We must collect clearer liquid without carrying all the sediment.', '{"major_concepts": "Transfer and Filter", "practical_operation": "Decant from Jar A into Jar B without disturbing settled soil; pass the liquid through filter paper into Cup C; keep vessel IDs attached to readings.", "source": "Jar A after settling; Jar B collected 185 mL; Cup C after filtration 175 mL (worked model)."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Transfer and Filter; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'We must collect clearer liquid without carrying all the sediment.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 6, "level": 1, "capability_id": "RMR-CAP-L01-M02", "source_record": "Jar A after settling; Jar B collected 185 mL; Cup C after filtration 175 mL (worked model).", "limitation": "Clearer appearance is not proof of drinking-water safety.", "drive_folder": "https://drive.google.com/drive/folders/1CUzKJA90kknr9Objm4a0ch4y-fqw6bCF", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
