VALUES ('db1a4536-64f3-5d40-b654-7853dbf44220'::uuid, '03bd758a-832c-5e49-92ff-9119d32994a5'::uuid, 3, 'Calculate the Collected Volume', 'Solve the connected River Mission challenge: The volume collected at the end is lower than the starting amount. Deliverable: A labelled volume, fraction and percentage calculation record.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'A school water team receives muddy water and must observe settling, separate the clearer liquid, measure what is collected, and explain what the experiment does not prove.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Match vessel and volume; subtract 200 - 175 = 25 mL; simplify 25/200 = 1/8; calculate 12.5% not collected and 87.5% collected.", "Explain the limits of the result", "Create A labelled volume, fraction and percentage calculation record."]'::jsonb, 'Use this module when investigating: The volume collected at the end is lower than the starting amount.', '{"major_concepts": "Calculate the Collected Volume", "practical_operation": "Match vessel and volume; subtract 200 - 175 = 25 mL; simplify 25/200 = 1/8; calculate 12.5% not collected and 87.5% collected.", "source": "Worked model: Jar A start 200 mL, Jar B 185 mL, Cup C final 175 mL."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Calculate the Collected Volume; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'The volume collected at the end is lower than the starting amount.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 6, "level": 1, "capability_id": "RMR-CAP-L01-M03", "source_record": "Worked model: Jar A start 200 mL, Jar B 185 mL, Cup C final 175 mL.", "limitation": "The 25 mL difference is not the dry mass of mud removed.", "drive_folder": "https://drive.google.com/drive/folders/14uBbiZj5REpuCg2mk5XDv67upPWwYc_e", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
