safety.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 6, "level": 1, "capability_id": "RMR-CAP-L01-M04", "source_record": "Worked jar and filter results, with a separate school-tank decision question.", "limitation": "Do not claim that the school tank is safe to drink from.", "drive_folder": "https://drive.google.com/drive/folders/1_dreqPPaU1Yo4Fjl55FxNwXTWjMfwFbH", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
