VALUES ('9fefeb20-0e05-537e-bbb3-e47937941b7d'::uuid, '91ce2164-4d53-5ef3-adb1-691e2c6c4209'::uuid, 1, 'Test the Three Coded Liquids', 'Solve the connected River Mission challenge: Three clear-looking samples may produce different indicator responses. Deliverable: A coded-sample litmus observation table.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Three similar-looking liquids give different indicator evidence. The student team must record tests, investigate a conflict and report reliable observations without guessing.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Keep cup IDs separate; compare each recorded strip before and after testing; enter the colour observation without assuming the category.", "Explain the limits of the result", "Create A coded-sample litmus observation table."]'::jsonb, 'Use this module when investigating: Three clear-looking samples may produce different indicator responses.', '{"major_concepts": "Test the Three Coded Liquids", "practical_operation": "Keep cup IDs separate; compare each recorded strip before and after testing; enter the colour observation without assuming the category.", "source": "Three coded cups and separate red/blue litmus observations shown in the lesson."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Test the Three Coded Liquids; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'Three clear-looking samples may produce different indicator responses.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 7, "level": 2, "capability_id": "RMR-CAP-L02-M01", "source_record": "Three coded cups and separate red/blue litmus observations shown in the lesson.", "limitation": "A colour observation should not be replaced by an invented result.", "drive_folder": "https://drive.google.com/drive/folders/1FsnRrKo9m5Lv3u3vgml_7Tk7_tFy5WQL", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
