VALUES ('8f212e8b-7a24-5b92-95fb-4f40bf95498b'::uuid, '91ce2164-4d53-5ef3-adb1-691e2c6c4209'::uuid, 2, 'Investigate the Cup B Conflict', 'Solve the connected River Mission challenge: Cup B has contradictory blue-litmus records. Deliverable: A Cup B discrepancy and controlled-retest log.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Three similar-looking liquids give different indicator evidence. The student team must record tests, investigate a conflict and report reliable observations without guessing.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions.", "Explain the limits of the result", "Create A Cup B discrepancy and controlled-retest log."]'::jsonb, 'Use this module when investigating: Cup B has contradictory blue-litmus records.', '{"major_concepts": "Investigate the Cup B Conflict", "practical_operation": "Retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions.", "source": "B-T1 blue turns red; B-T2 unchanged with missing conditions; worked B-T3 fresh blue turns red."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Investigate the Cup B Conflict; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'Cup B has contradictory blue-litmus records.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 7, "level": 2, "capability_id": "RMR-CAP-L02-M02", "source_record": "B-T1 blue turns red; B-T2 unchanged with missing conditions; worked B-T3 fresh blue turns red.", "limitation": "Do not claim contamination or another cause unless proven.", "drive_folder": "https://drive.google.com/drive/folders/1_N2i7fEy2mHTGr-NLnsQU8RyiRlHBFo2", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
