VALUES ('8b541021-0098-5131-8b12-b75a46b266d0'::uuid, '91ce2164-4d53-5ef3-adb1-691e2c6c4209'::uuid, 3, 'Observe the Turmeric Response', 'Solve the connected River Mission challenge: A different indicator may provide useful evidence about a sample. Deliverable: A turmeric observation and cross-indicator comparison.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Three similar-looking liquids give different indicator evidence. The student team must record tests, investigate a conflict and report reliable observations without guessing.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Record original indicator colour and visible colour after contact; compare with the provided reference and the litmus log.", "Explain the limits of the result", "Create A turmeric observation and cross-indicator comparison."]'::jsonb, 'Use this module when investigating: A different indicator may provide useful evidence about a sample.', '{"major_concepts": "Observe the Turmeric Response", "practical_operation": "Record original indicator colour and visible colour after contact; compare with the provided reference and the litmus log.", "source": "The turmeric and liquid-sample observations displayed in the module."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Observe the Turmeric Response; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'A different indicator may provide useful evidence about a sample.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 7, "level": 2, "capability_id": "RMR-CAP-L02-M03", "source_record": "The turmeric and liquid-sample observations displayed in the module.", "limitation": "Colour must be observed or supplied; do not fabricate a reaction.", "drive_folder": "https://drive.google.com/drive/folders/1CYzANtzXN-tUUFKkNF9bDvwHc_HbCJcA", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
