VALUES ('cee846f5-aff7-5d03-b454-6c58c4b82072'::uuid, '91ce2164-4d53-5ef3-adb1-691e2c6c4209'::uuid, 4, 'Finish the Cost and Finding Log', 'Solve the connected River Mission challenge: The testing team must record findings and the cost of strips. Deliverable: A verified cost calculation and scientific finding log.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Three similar-looking liquids give different indicator evidence. The student team must record tests, investigate a conflict and report reliable observations without guessing.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports.", "Explain the limits of the result", "Create A verified cost calculation and scientific finding log."]'::jsonb, 'Use this module when investigating: The testing team must record findings and the cost of strips.', '{"major_concepts": "Finish the Cost and Finding Log", "practical_operation": "Multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports.", "source": "Strip counts, stated unit prices, the available budget and observation records in the module."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Finish the Cost and Finding Log; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'The testing team must record findings and the cost of strips.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 7, "level": 2, "capability_id": "RMR-CAP-L02-M04", "source_record": "Strip counts, stated unit prices, the available budget and observation records in the module.", "limitation": "A low testing cost does not make incomplete findings conclusive.", "drive_folder": "https://drive.google.com/drive/folders/1OpZ8t7arqFDZDesRq__0YPyPJDuuBOQh", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
