VALUES ('dd0f9e64-be80-5723-af2b-0164271daf17'::uuid, '33cad490-ae39-590a-8121-182638ceff97'::uuid, 1, 'Compare the Two Field Reports', 'Solve the connected River Mission challenge: Two runoff reports describe different sites, but conditions may not match. Deliverable: A two-report comparison and list of missing controls.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Rainwater runs off bare and covered ground differently. The team must compare field reports, set matched conditions, calculate runoff and design a fair field study.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly.", "Explain the limits of the result", "Create A two-report comparison and list of missing controls."]'::jsonb, 'Use this module when investigating: Two runoff reports describe different sites, but conditions may not match.', '{"major_concepts": "Compare the Two Field Reports", "practical_operation": "Align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly.", "source": "Field reports F1 and F2 with site, rainfall and land-cover details."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Compare the Two Field Reports; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'Two runoff reports describe different sites, but conditions may not match.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 8, "level": 3, "capability_id": "RMR-CAP-L03-M01", "source_record": "Field reports F1 and F2 with site, rainfall and land-cover details.", "limitation": "Different conditions must not be presented as a controlled experiment.", "drive_folder": "https://drive.google.com/drive/folders/109zvdaJ7gV-rCzuvXR7NVt5oSurKihV_", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
