VALUES ('8d9d5aa3-8e63-52b3-8dee-f5d2e5c88d1a'::uuid, '33cad490-ae39-590a-8121-182638ceff97'::uuid, 2, 'Build a Matched Runoff Comparison', 'Solve the connected River Mission challenge: We want to test whether leaf cover changes runoff. Deliverable: A matched runoff setup and measurement record.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Rainwater runs off bare and covered ground differently. The team must compare field reports, set matched conditions, calculate runoff and design a fair field study.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings.", "Explain the limits of the result", "Create A matched runoff setup and measurement record."]'::jsonb, 'Use this module when investigating: We want to test whether leaf cover changes runoff.', '{"major_concepts": "Build a Matched Runoff Comparison", "practical_operation": "Compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings.", "source": "Bare-soil and leaf-covered trays; collection vessels and matched input conditions."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Build a Matched Runoff Comparison; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'We want to test whether leaf cover changes runoff.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 8, "level": 3, "capability_id": "RMR-CAP-L03-M02", "source_record": "Bare-soil and leaf-covered trays; collection vessels and matched input conditions.", "limitation": "Do not assign sediment scores without recorded observations.", "drive_folder": "https://drive.google.com/drive/folders/1DqVCJKrE-bA3xk6DhKejJvhmuVyj3A2j", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
