VALUES ('7737a5b4-11cb-5ebb-a6f0-bade5c1b4d3e'::uuid, '33cad490-ae39-590a-8121-182638ceff97'::uuid, 3, 'Calculate Runoff Across Three Trials', 'Solve the connected River Mission challenge: Three trials give different volumes, so a fair numerical comparison is needed. Deliverable: A three-trial mean, percentage and comparison table.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Rainwater runs off bare and covered ground differently. The team must compare field reports, set matched conditions, calculate runoff and design a fair field study.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Calculate means 160 mL and 100 mL; compute 64% and 40% runoff; report the 24-percentage-point gap.", "Explain the limits of the result", "Create A three-trial mean, percentage and comparison table."]'::jsonb, 'Use this module when investigating: Three trials give different volumes, so a fair numerical comparison is needed.', '{"major_concepts": "Calculate Runoff Across Three Trials", "practical_operation": "Calculate means 160 mL and 100 mL; compute 64% and 40% runoff; report the 24-percentage-point gap.", "source": "Bare runoff: 150, 160, 170 mL; covered: 90, 100, 110 mL; input 250 mL per trial."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Calculate Runoff Across Three Trials; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'Three trials give different volumes, so a fair numerical comparison is needed.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 8, "level": 3, "capability_id": "RMR-CAP-L03-M03", "source_record": "Bare runoff: 150, 160, 170 mL; covered: 90, 100, 110 mL; input 250 mL per trial.", "limitation": "24 percentage points is a runoff-share gap, not dry soil mass lost.", "drive_folder": "https://drive.google.com/drive/folders/1VmF5FhLiw5aRCRnHNazhhELKbyH_hqFr", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
