orkbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 9, "level": 4, "capability_id": "RMR-CAP-L04-M02", "source_record": "Separate SOIL-S and SOL-B filtration records and apparatus shown in the module.", "limitation": "Visible filtration alone does not prove dissolved salt removal.", "drive_folder": "https://drive.google.com/drive/folders/1LwYutfg52OaySlKrqANdg3R2neD4FXQ1", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
