VALUES ('20540d62-eec3-5010-9a5c-4792804ec826'::uuid, 'd3772820-8f5a-53d8-ad3a-ae2299f8de36'::uuid, 1, 'Compare Teacher-Prepared Reference Liquids', 'Solve the connected River Mission challenge: Similar-looking reference liquids can have different acid-base responses. Deliverable: A sample-by-sample indicator evidence table.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Water samples look clear, but their safety is unknown. The team must examine pH information, inspect mock instrument records and report missing tests before advising an authority.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Match each strip to its own sample, compare observed colours with the correct kit chart and record the classification.", "Explain the limits of the result", "Create A sample-by-sample indicator evidence table."]'::jsonb, 'Use this module when investigating: Similar-looking reference liquids can have different acid-base responses.', '{"major_concepts": "Compare Teacher-Prepared Reference Liquids", "practical_operation": "Match each strip to its own sample, compare observed colours with the correct kit chart and record the classification.", "source": "Teacher-prepared reference samples, indicator strips and the applicable manufacturer chart."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Compare Teacher-Prepared Reference Liquids; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'Similar-looking reference liquids can have different acid-base responses.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 10, "level": 5, "capability_id": "RMR-CAP-L05-M01", "source_record": "Teacher-prepared reference samples, indicator strips and the applicable manufacturer chart.", "limitation": "The reference chart must be supplied; pH or appearance alone is not safety proof.", "drive_folder": "https://drive.google.com/drive/folders/14v4VAVNT3cTVJHe4yEpu6kYX5xJU2V-k", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
