VALUES ('9cb55360-8f65-5be5-b880-f83e1c401086'::uuid, 'd3772820-8f5a-53d8-ad3a-ae2299f8de36'::uuid, 3, 'Review an Unverified Acid-Base Protocol', 'Solve the connected River Mission challenge: A described experiment is not proof that its result was observed. Deliverable: A procedure audit showing the observations still needed.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Water samples look clear, but their safety is unknown. The team must examine pH information, inspect mock instrument records and report missing tests before advising an authority.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["List the described steps, identify the missing starting and final evidence and classify the outcome as unverified.", "Explain the limits of the result", "Create A procedure audit showing the observations still needed."]'::jsonb, 'Use this module when investigating: A described experiment is not proof that its result was observed.', '{"major_concepts": "Review an Unverified Acid-Base Protocol", "practical_operation": "List the described steps, identify the missing starting and final evidence and classify the outcome as unverified.", "source": "Acid-base procedure without verified before-and-after observations."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Review an Unverified Acid-Base Protocol; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'A described experiment is not proof that its result was observed.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 10, "level": 5, "capability_id": "RMR-CAP-L05-M03", "source_record": "Acid-base procedure without verified before-and-after observations.", "limitation": "Do not manufacture an acid-base change or claim an experiment was completed.", "drive_folder": "https://drive.google.com/drive/folders/18EMpRmMCffqFkRbH-L14f45LLzKieodW", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
