VALUES ('1df01a94-b22e-54d7-a4d4-d8aee8c969da'::uuid, 'd3772820-8f5a-53d8-ad3a-ae2299f8de36'::uuid, 5, 'Prepare the Water-Authority Handover', 'Solve the connected River Mission challenge: The authority needs a justified decision rather than a guess about safety. Deliverable: A water-authority handover note with evidence and unresolved questions.', '["Unclear evidence", "Missing or inconsistent readings", "Incorrect units", "Unsupported final claim"]'::jsonb, '["Learner may skip source IDs, confuse observed vs illustrative results, or infer a conclusion not supported by evidence."]'::jsonb, 'Water samples look clear, but their safety is unknown. The team must examine pH information, inspect mock instrument records and report missing tests before advising an authority.', '["Read the previous module output and basic science measurements", "Identify source IDs before calculating"]'::jsonb, '["Summarise verified observations, missing measurements, limits and the responsible next testing or referral action.", "Explain the limits of the result", "Create A water-authority handover note with evidence and unresolved questions."]'::jsonb, 'Use this module when investigating: The authority needs a justified decision rather than a guess about safety.', '{"major_concepts": "Prepare the Water-Authority Handover", "practical_operation": "Summarise verified observations, missing measurements, limits and the responsible next testing or referral action.", "source": "Completed Level 5 sample, pH, instrument and source-evidence reviews."}'::jsonb, '{"teacher_support": "safe home/school observation only; require adult supervision when handling test solutions; no student AI required"}'::jsonb, '{"technical_concepts_learnt": "Prepare the Water-Authority Handover; source evidence; method; units; uncertainty; decision boundary"}'::jsonb, 'The authority needs a justified decision rather than a guess about safety.', '{"items": ["Beakers, safe sample containers and source records as shown in deck; learner workbook (.xlsx)"]}'::jsonb, TRUE, TRUE, '{"class": 10, "level": 5, "capability_id": "RMR-CAP-L05-M05", "source_record": "Completed Level 5 sample, pH, instrument and source-evidence reviews.", "limitation": "No water-use clearance without the necessary accredited safety testing.", "drive_folder": "https://drive.google.com/drive/folders/1tvzCRd-QwvgSdeN8hJLHU9Czp2Nid_8S", "source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";



