VALUES ('4a7943b8-c3b8-5759-a258-1f97a9c19744'::uuid, '8f9a3abc-1a79-5fca-a675-ff688005f55d'::uuid, 'slide'::public.content_type, 'Express - Prepare the Water-Authority Handover', 'Explain what the worked evidence supports, using named sample IDs, observations and units. Identify the scientific limitation: No water-use clearance without the necessary accredited safety testing.', 'https://bucket.lte.rareminds.in/resources/capabilities/RMR-CAP-L05/levels/RMR-L05/modules-5/content/04_Express.pptx', 4, NULL, NULL, 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 183033, 1, 'published'::public.content_publish_status, '{"source": "Approved 6E PPTX uploaded to RAREMINDS School Google Drive", "level": 5, "module": 5, "source_record": "Completed Level 5 sample, pH, instrument and source-evidence reviews.", "stage": "express", "asset_file_name": "04_Express.pptx"}'::jsonb)
