VALUES ('b73d26f7-d577-5e7e-adb6-2e0c6d3778ab'::uuid, '72f8c5d5-3d4d-54ce-a9f4-e21595f9b9cb'::uuid, 'slide'::public.content_type, 'Empower - Prepare the Water-Authority Handover', 'Apply the same method to the distinct practice source in the slide file. Summarise verified observations, missing measurements, limits and the responsible next testing or referral action. Record the learner’s own result and check units.', 'https://bucket.lte.rareminds.in/resources/capabilities/RMR-CAP-L05/levels/RMR-L05/modules-5/content/05_Empower.pptx', 5, NULL, NULL, 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 191922, 1, 'published'::public.content_publish_status, '{"source": "Approved 6E PPTX uploaded to RAREMINDS School Google Drive", "level": 5, "module": 5, "source_record": "Completed Level 5 sample, pH, instrument and source-evidence reviews.", "stage": "empower", "asset_file_name": "05_Empower.pptx"}'::jsonb)
