INSERT INTO public."artifact_questions" ("id", "artifact_id", "question_order", "title", "description", "instructions", "is_active", "metadata")
VALUES ('76f4a5c6-d482-5232-87d1-2843c22043e8'::uuid, 'd132506e-3e6d-58b7-8bc6-e104cc0c2564'::uuid, 1, 'Complete the A settling observation log with an accurate explanation of what stayed in the jar', 'Use the supplied River Mission source record and produce: A settling observation log with an accurate explanation of what stayed in the jar.', '{"required_fields": "Read the source: Model A muddy-water jar; starting water 200 mL, soil 5 g, settling time 15 min. Record named observations and working steps in the blue learner cells. Keep measurement units; show calculations where required; complete the independent Evolve case. Do not claim missing or unverified results. Settling does not prove that water is safe to drink.", "pass_criteria": "", "critical_fail": ""}'::jsonb, TRUE, '{"source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification", "answer_key_in_learner_file": false, "artifact": "A settling observation log with an accurate explanation of what stayed in the jar.", "critical_error": "Settling does not prove that water is safe to drink."}'::jsonb)
ON CONFLICT DO NOTHING;
INSERT INTO public."artifact_questions" ("id", "artifact_id", "question_order", "title", "description", "instructions", "is_active", "metadata")
VALUES ('b6146c1b-0f7f-5c54-8f4b-c530eb6e5b51'::uuid, 'c9d47dd7-6611-52af-b00c-cec5ea44f8d7'::uuid, 1, 'Complete the Transfer-and-filtration evidence with the collected volume', 'Use the supplied River Mission source record and produce: Transfer-and-filtration evidence with the collected volume.', '{"required_fields": "Read the source: Jar A after settling; Jar B collected 185 mL; Cup C after filtration 175 mL (worked model). Record named observations and working steps in the blue learner cells. Keep measurement units; show calculations where required; complete the independent Evolve case. Do not claim missing or unverified results. Clearer appearance is not proof of drinking-water safety.", "pass_criteria": "", "critical_fail": ""}'::jsonb, TRUE, '{"source": "RAREMINDS River Mission Grades 6-10, approved module and 6E content stored in linked Google Drive assets; career role labels are for exploration, not certification", "answer_key_in_learner_file": false, "artifact": "Transfer-and-filtration evidence with the collected volume.", "critical_error": "Clearer appearance is not proof of drinking-water safety."}'::jsonb)
